                    & VIS & STC & KREL & MP & INVc & PQ & EOUT & PROG & ST11). cbn [cfg_ms cfg_model] in *.
  pose proof INVc as (MI & ST & [errv ERR] & AUX & RH & FR & SD & PC & EC & EOK & RDI & HC & FTS & U & HO & L & BUD & FSX & INX & XP & ALOK & AMON & PR).
  destruct FR as (j0 & j160 & j184 & ja & j48 & jb & j80 & jc & j112 & LOC & GAP & SAV & FFR & SH & FL). destruct SD as (RF & AC & SK & ACP & ACE & ACW & SVE & SVW).
  pose proof (env_facts H HH MX CX X XOK) as EF. destruct EF as (Pl & Ph & APP & FOP & El & Eh & APE & FOE & Wl & Wh & APW & FOW & CEIL & LO & SPAR & SPH).
  pose proof (stat_open H MX CX X XOK) as SO. destruct SO as (N1 & _ & _ & PAL & EAL & DPE & QP & QE & AL16 & SHI & NR & SPB & TP & MXLE & CXLE).
  unfold BPUT_STACK in LO. rewrite OCB_STACK_val in LO.
  eapply (ahh_evt H HH); [exact KREL| exact VIS| |].
  { eapply (bp_done H HH (fun ms' => exists m' j5,
        ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (q - p0)) (wz fp) (wz ff) (wz ff) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (ret_pc ra) fc None m' (seg_rom bsegs)
        /\ munch [(ff, ff + 8); (sh ff, sh ff + 16); (fp, fp + 1)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
        /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi /\ stk bsegs m' lo (bv_unsigned sp)));
      [exact LOC| exact GAP| exact GSZ| exact SAV| exact SPA| exact ST| exact CEIL| clear - LO SPAR; lia| exact FFR| exact SH| exact FL
      | exact FF| exact RF| exact AC| exact SK| exact MI| clear - Wl; unfold AIMG_TOP in Wl; lia| unfold X8_BP_put4.p1 in PR; clear - PR Wh Wl N1; pose proof aceil_facts; unfold AIMG_TOP in Wl; lia |].
    intros m' j5 MU WM MI' RF' AC' SK' ST' FFR' SH' FL'. exists m', j5. repeat (split; [first [reflexivity| assumption]|]). exact ST'. }
  intros msF' mo' KREL' MP' (m' & j5 & VIS' & MU & WM & MI' & RF' & AC' & SK' & ST').
  assert (FW3 : Forall (wg H X) [(ff, ff + 8); (sh ff, sh ff + 16); (fp, fp + 1)]%Z).
  { unfold wg, wg7. repeat apply Forall_cons; [| | | apply Forall_nil]; cbn [fst snd].
    - left. right; right; right; right; left. clear; lia.
