  assert (FNC : Forall (fun iv : Z * Z => AG_HTTP_CAT + 64 <= fst iv \/ snd iv <= AG_HTTP_CAT) [(ff, ff + 8); (sh ff, sh ff + 16); (fp, fp + 1)]%Z).
  { pose proof (frame_facts H MX CX X XOK) as (F1 & _ & _ & _ & F4 & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & SF1 & _).
    unfold AIMG_TOP, AFS_HDR, AFS_FLAGS, AG_HTTP_CAT in *. repeat apply Forall_cons; [| | | apply Forall_nil]; cbn [fst snd]; left; clear - F1 F4 SF1; lia. }
  pose proof (w3_sep_all) as W3S.
  destruct (W3S P PARSER_SIZE FOP APP ltac:(unfold PARSER_SIZE; clear; lia)) as [DP _].
  destruct (W3S E 24 FOE APE ltac:(clear; lia)) as [DE _].
  pose proof (dtor_facts d m' ltac:(eapply (keep_U H HH MX CX X XOK); [exact FW3| exact MU| exact WM| exact RH| exact L| exact U]) L) as [HD BD].
  unfold put_done, bput_post. cbn [cfg_ms cfg_model].
  exists t0, t1, t2, (wz fp), (wz ff), (wz ff), a4, a5, a6, a7, t3, t4, t5, t6, m', errv, s, d, q, E', XS.
  split; [exact VIS'|]. split; [exact KREL'|]. split; [eapply (ah_mpres_trans H HH); [exact MP| exact MP']|].
