Definition put_res (p : Z) (cf : config) : Prop :=
  DONE cf \/ exists p', p < p' < p1 /\ AT BP_DISP (fun st => st <> 11) p' cf.

Lemma sr_tail : forall p q cf, MID BP_TAIL (fun c E' => E' = EC_clear) p q cf -> as_SR H (put_res p) cf.
Proof.
  open_X. intros p q [ms mo] MIDc.
  destruct MIDc as (rax & t0 & t1 & t2 & a0 & a1 & a2 & a3 & a4 & a5 & a6 & a7 & t3 & t4 & t5 & t6 & n & s & d & m & E' & XS
                    & VIS & STC & KREL & MP & INVc & PQ & EOUT & PROG & ST11). cbn [cfg_ms cfg_model] in *. cbv beta in STC. subst E'.
  pose proof INVc as (MI & ST & [errv ERR] & AUX & RH & FR & SD & PC & EC & EOK & RDI & HC & FTS & U & HO & L & BUD & FSX & INX & XP & ALOK & AMON & PR).
  destruct FR as (j0 & j160 & j184 & ja & j48 & jb & j80 & jc & j112 & LOC & GAP & SAV & FFR & SH & FL). destruct SD as (RF & AC & SK & ACP & ACE & ACW & SVE & SVW).
  pose proof (env_facts H HH MX CX X XOK) as (Pl & Ph & APP & FOP & El & Eh & APE & FOE & Wl & Wh & APW & FOW & CEIL & LO & SPAR & SPH).
  pose proof (stat_open H MX CX X XOK) as (N1 & _ & _ & PAL & _).
  pose proof L as (PCOK & _). unfold X8_BP_put4.p1 in PR.
  eapply (ahh_evt_then H HH); [exact KREL| exact VIS| |].
  { eapply bp_tail; [exact PC| exact PCOK| exact LOC| exact ACP| exact PAL| exact MI| clear - Wl; unfold AIMG_TOP in Wl; lia| clear - PR; lia| unfold X8_BP_put4.p1; clear - PR; lia
      | unfold X8_BP_put4.p1; clear - Wh; pose proof aceil_facts; lia]. }
  intros msF' mo' KREL' MP' (a0' & a1' & a2' & [VIS' | (VIS' & QP1 & N11 & EG)]).
  - (* [comment removed for export] *) eapply (ah_seq H HH); [apply (sr_done (fun _ _ => True) p q)| intros c' D; apply (ah_done H HH); left; exact D]. unfold put_mid. cbn [cfg_ms cfg_model].
    exists rax, t0, t1, t2, a0', a1', a2', a3, a4, a5, a6, a7, t3, t4, t5, t6, n, s, d, m, EC_clear, XS.
    split; [exact VIS'|]. split; [exact I|]. split; [exact KREL'|]. split; [eapply (ah_mpres_trans H HH); [exact MP| exact MP']|].
    split; [exact INVc|]. split; [exact PQ|]. split; [left; reflexivity|]. split; [exact PROG| exact ST11].
  - (* [comment removed for export] *) apply (ah_done H HH). right. exists q. split; [destruct (PROG eq_refl) as [K|K]; [clear - K QP1; lia| exfalso; exact (N11 K)]|].
    unfold put_at. cbn [cfg_ms cfg_model].
    exists rax, t0, t1, t2, a0', a1', a2', a3, a4, a5, a6, a7, t3, t4, t5, t6, s, d, m, XS.
    split; [exact VIS'|]. split; [exact N11|]. split; [exact KREL'|]. split; [eapply (ah_mpres_trans H HH); [exact MP| exact MP']|].
    exact INVc.
Qed.

